"""Plain-English ML concepts used in this project (shown by the API at /api/ml/insights and printed on the last page of the report)."""
CONCEPTS = [
 dict(term="Train / test split", summary="Hide part of the data while the model learns, then score it on the hidden part, so we test understanding and not memory.", example="A student practises on past papers and is judged on a new paper."),
 dict(term="Temporal split", summary="Train on the past and test on the future, never the other way round, so no future information leaks into training.", example="Predict next week's bus crowding from the previous three weeks only."),
 dict(term="Feature scaling (StandardScaler)", summary="Rescale every column to a similar range so no column dominates only because its numbers are bigger.", example="Distance in km and hour of day are put on the same scale before KNN measures 'closeness'."),
 dict(term="Winsorizing", summary="Cut extreme values back to the 1st and 99th percentile of the training data so a few huge numbers cannot distort the model.", example="One day with a ticket-system glitch is capped instead of ruining the average."),
 dict(term="Linear Regression (OLS)", summary="Fits the best straight line (a weighted sum of features) through the data to predict a number.", example="Predicting house price from size, bedrooms and age."),
 dict(term="Ridge and Lasso (regularisation)", summary="Linear regression with a brake: Ridge shrinks all weights, Lasso can shrink some to exactly zero, which also selects features.", example="A teacher who stops you explaining a result with too many reasons."),
 dict(term="Elastic Net", summary="A mix of Ridge and Lasso, useful when several features overlap.", example="Latitude, longitude and distance to the centre all describe 'where', so their weights are shared sensibly."),
 dict(term="KNN (K-Nearest Neighbours)", summary="To predict a new case, look at the K most similar known cases and let them vote (or average them).", example="Judging a restaurant by the ratings of the 10 most similar ones nearby."),
 dict(term="SVM (Support Vector Machine)", summary="Draws the boundary between classes with the widest possible safety margin; with a kernel the boundary can curve.", example="Separating spam from normal mail with the cleanest dividing line."),
 dict(term="Decision Tree", summary="A flow-chart of yes/no questions that ends in an answer; easy to read but can memorise noise if too deep.", example="A doctor's triage chart."),
 dict(term="Random Forest", summary="Many different trees vote and their answers are averaged, which is steadier than any single tree.", example="Asking 200 people to guess the sweets in a jar and taking the average."),
 dict(term="Gradient Boosting", summary="Builds trees one after another, each fixing the mistakes of the previous ones.", example="A student who redoes only the questions they got wrong, round after round."),
 dict(term="Logistic Regression", summary="A linear model that outputs the probability of each class instead of a number.", example="A bank estimating the chance a loan will be repaid."),
 dict(term="Naive Bayes", summary="Classifies using probabilities and pretends the features are independent, which makes it very fast.", example="Spam filters multiply the probabilities of the words in a mail."),
 dict(term="K-Means clustering", summary="With no labels, groups similar items by repeatedly moving K group centres to the middle of their members.", example="Grouping bus routes into 'morning commuter' and 'all-day' types."),
 dict(term="PCA (Principal Component Analysis)", summary="Squeezes many columns into a few new ones that keep most of the information, so data can be drawn on a 2-D plot.", example="Plotting routes described by six numbers on a single flat map."),
 dict(term="Cross-validation", summary="Repeats the train/test experiment several times on different hidden parts and averages the scores, so one lucky split cannot fool us.", example="Five mock exams instead of one."),
 dict(term="GridSearchCV (hyper-parameter tuning)", summary="Tries every combination of a model's settings with cross-validation and keeps the best.", example="Trying several oven temperatures and times to find the best cake."),
 dict(term="Overfitting", summary="The model memorises the training data and does worse on new data; shown by a big gap between train and test scores.", example="Learning last year's answers by heart instead of the subject."),
 dict(term="MAE, RMSE and R2", summary="MAE is the average size of the error, RMSE punishes big errors more, R2 is the share of variation explained (1 perfect, 0 no better than the average).", example="An exam score shows how far off you were on average."),
 dict(term="Accuracy, macro-F1 and confusion matrix", summary="Accuracy is the share of correct labels; macro-F1 treats every class equally, even rare ones; the confusion matrix shows which classes get mixed up.", example="A spam filter that is 95% accurate but never catches a rare scam would score poorly on macro-F1."),
]
